// P1AM-100: Tank pump control with low/high float switches.
// Slot 1: Discrete Input Module
//   Channel 1: Low Float Switch (NO) - Turns ON when water is low.
//   Channel 2: High Float Switch (NO) - Turns ON when water is high.
// Slot 2: Discrete Output Module
//   Channel 1: Pump Contactor.
// Logic: Start pump when Low float is ON (water low). Stop pump when High float is ON (water high).
// The pump runs if Low is ON AND High is OFF.

#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs: NO switches are HIGH when activated.
  bool lowFloat = P1.readDiscrete(inSlot, 1); // ON when water is low
  bool highFloat = P1.readDiscrete(inSlot, 2); // ON when water is high

  // Logic: Pump runs if Low is ON (needs water) AND High is OFF (not full yet).
  // If High is ON, we stop. If Low is OFF (water is high enough), we stop.
  bool pumpOn = lowFloat && !highFloat;

  // Write output: Turn the pump contactor on or off.
  P1.writeDiscrete(pumpOn, outSlot, 1);
}
```

