language arduino
// This sketch lights the LED on pin 13 only while the button on pin 2 is held down.
// Wiring: Button between pin 2 and GND.
// The internal pull-up resistor is enabled, so the pin reads HIGH when open
// and LOW when the button is pressed.

const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Enable internal pull-up resistor
  pinMode(ledPin, OUTPUT);          // Set LED pin as output
}

void loop() {
  // Read the button state. LOW means pressed (connected to ground).
  int buttonState = digitalRead(buttonPin);

  if (buttonState == LOW) {
    digitalWrite(ledPin, HIGH); // Turn LED on
  } else {
    digitalWrite(ledPin, LOW);  // Turn LED off
  }
}
END

