language python
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 sales_max.py sales.csv")
        return

    filename = sys.argv[1]
    max_val = None

    try:
        with open(filename, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                # Assuming the column is named 'amount'
                if 'amount' in row:
                    try:
                        val = float(row['amount'])
                        if max_val is None or val > max_val:
                            max_val = val
                    except ValueError:
                        # Skip rows where amount is not a valid number
                        pass

        if max_val is not None:
            print(f"Largest value in amount column: {max_val}")
        else:
            print("No valid numeric values found in the 'amount' column.")

    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
    except Exception as e:
        print(f"Error reading file: {e}")

if __name__ == "__main__":
    main()
END

